import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if we have enough patients and features
    if feats.n < 10 or len(feats.ids) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Look for strong associations with outcome
    correlations = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            # For clinical/cohort variables, check correlation with outcome
            corr = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            correlations.append((abs(corr), fid, i))
        else:
            # For other variables, use t-test statistic
            y0 = feats.x[feats.y == 0, i]
            y1 = feats.x[feats.y == 1, i]
            if len(y0) > 1 and len(y1) > 1:
                t_stat, _ = stats.ttest_ind(y0, y1)
                correlations.append((abs(t_stat), fid, i))

    # Sort by strength of association
    correlations.sort(reverse=True)

    # If no strong associations found, return empty design
    if not correlations or correlations[0][0] < 1.0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features
    top_features = [fid for _, fid, _ in correlations[:MAX_DRIVERS]]

    # Check for near-duplicates
    to_remove = set()
    for i, fid1 in enumerate(top_features):
        for j, fid2 in enumerate(top_features[i+1:], i+1):
            if fid1 in to_remove or fid2 in to_remove:
                continue
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            if abs(np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0, 1]) > 0.6:
                to_remove.add(fid2)

    # Remove duplicates
    final_features = [fid for fid in top_features if fid not in to_remove]

    # Try to find a primary driver (strongest correlation)
    primary_driver = None
    if final_features:
        # Find the one with highest absolute correlation with outcome
        max_corr = -1
        for fid in final_features:
            col_idx = feats.column(fid)
            corr = np.corrcoef(feats.x[:, col_idx], feats.y)[0, 1]
            if abs(corr) > max_corr:
                max_corr = abs(corr)
                primary_driver = fid

    # If we have a driver, use it to adjust for confounding
    if primary_driver:
        driver_col = feats.column(primary_driver)
        # Use this as a weighted score
        weights = {primary_driver: 1.0}
        # Include all features that aren't too highly correlated with driver
        columns = [fid for fid in final_features if fid != primary_driver]
        # Add some interaction terms with the driver
        products = [(primary_driver, fid) for fid in columns[:3] if fid != primary_driver]
        return Design(
            drivers=(primary_driver,),
            columns=tuple(columns),
            products=tuple(products),
            loadings=weights
        )
    else:
        # No clear driver, just return the best features
        return Design(
            drivers=(),
            columns=tuple(final_features),
            products=(),
            loadings={}
        )

